gB2(){return"\u0420\u0435\u0436\u0438\u043c \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0430 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0434\u043b\u044f \u0441\u0446\u0435\u043d"},
gAI(){return"\u041c\u0430\u043a\u0435\u0442 \u0433\u0430\u043b\u0435\u0440\u0435\u0439"},
